mapper.select:
select u.id, u.username, u.openid, u.role, u.status, ui.nickname, ui.avatar, ui.phone, ui.email, ui.major, ui.gender, ui.sign, ui.birthday from user u left join user_info ui on u.id = ui.user_id where 1=1
and (u.username like concat('%', #{keyword}, '%') or ui.nickname like concat('%', #{keyword}, '%'))
order by u.id desc limit #{offset}, #{size}
